package com.notificationservice.presentation.response; import com.notificationservice.domain.model.*; import java.time.Instant; import java.util.UUID;
public record NotificationResponse(UUID id,NotificationType type,String title,String content,String referenceId,String referenceType,boolean read,Instant readAt,Instant createdAt,String actionUrl,String actionLabel){public static NotificationResponse from(Notification n){String t=n.getReferenceType()==null?"":n.getReferenceType().toUpperCase();String url=switch(t){case "QUESTION"->n.getReferenceId()==null?null:"/questions/"+n.getReferenceId();case "AI_JOB","AIJOB"->n.getReferenceId()==null?null:"/ai/jobs/"+n.getReferenceId();case "EXAM"->n.getReferenceId()==null?null:"/exams/"+n.getReferenceId();case "USER","USER_PROFILE","USER_APPROVAL"->n.getReferenceId()==null?null:"/admin/users/"+n.getReferenceId();case "CONTACT_REQUEST"->n.getReferenceId()==null?null:"/admin/contact?contactId="+n.getReferenceId();default->null;};return new NotificationResponse(n.getId(),n.getType(),n.getTitle(),n.getContent(),n.getReferenceId(),n.getReferenceType(),n.isRead(),n.getReadAt(),n.getCreatedAt(),url,url==null?null:"Mở nội dung liên quan");}}
